import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.DSQXGnvq.js";const u=JSON.parse('{"title":"初升大教程","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/index.md","filePath":"tutorial/index.md"}'),l={name:"tutorial/index.md"};function i(n,t,h,s,d,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="初升大教程" tabindex="-1">初升大教程 <a class="header-anchor" href="#初升大教程" aria-label="Permalink to &quot;初升大教程&quot;">​</a></h1><p>欢迎来到 PySpice 初升大教程！本教程专为<strong>初中、高中和高校学生</strong>设计，从零开始教学如何使用 Python 和 PySpice 进行电路仿真。</p><h2 id="这个教程适合谁" tabindex="-1">这个教程适合谁？ <a class="header-anchor" href="#这个教程适合谁" aria-label="Permalink to &quot;这个教程适合谁？&quot;">​</a></h2><ul><li>🎒 <strong>初中生</strong>：刚开始学习物理电学，想用电脑模拟课堂实验</li><li>📚 <strong>高中生</strong>：正在学习电磁学，希望动手验证复杂的电路定律</li><li>🎓 <strong>高校学生</strong>：需要深入理解电路分析、模拟电子和数字逻辑</li></ul><h2 id="你需要准备什么" tabindex="-1">你需要准备什么？ <a class="header-anchor" href="#你需要准备什么" aria-label="Permalink to &quot;你需要准备什么？&quot;">​</a></h2><ul><li>一台能运行 Python 的电脑（Windows、macOS 或 Linux）</li><li>对电路和物理的基本好奇心</li><li>（可选）会一点 Python 更好，但不会也没关系——我们会一步步教你</li></ul><h2 id="教程结构" tabindex="-1">教程结构 <a class="header-anchor" href="#教程结构" aria-label="Permalink to &quot;教程结构&quot;">​</a></h2><p>本教程按照中国<strong>人教版物理教材</strong>的知识顺序编排，分为三个级别：</p><table tabindex="0"><thead><tr><th>级别</th><th>章节数</th><th>适合人群</th></tr></thead><tbody><tr><td>📗 <a href="/pyspice/tutorial/middle-school/">初中篇</a></td><td>6 章</td><td>八年级、九年级学生</td></tr><tr><td>📘 <a href="/pyspice/tutorial/high-school/">高中篇</a></td><td>11 章</td><td>高一至高三学生</td></tr><tr><td>📙 <a href="/pyspice/tutorial/college/">高校篇</a></td><td>17 章</td><td>大学理工科学生</td></tr></tbody></table><h2 id="如何使用本教程" tabindex="-1">如何使用本教程？ <a class="header-anchor" href="#如何使用本教程" aria-label="Permalink to &quot;如何使用本教程？&quot;">​</a></h2><p>每一章都遵循相同的结构：</p><ol><li><strong>本节你将学到</strong> — 明确的学习目标</li><li><strong>知识回顾/情景引入</strong> — 从日常生活出发，建立物理直觉</li><li><strong>动手设计电路</strong> — 先画出电路图，手工计算预期结果</li><li><strong>用 Python 实现电路仿真</strong> — 用代码构建电路、运行仿真、分析结果</li><li><strong>深入理解</strong> — 对比手工计算与仿真结果</li><li><strong>本章小结</strong> — 核心要点回顾</li><li><strong>练习</strong> — 动手巩固</li></ol><blockquote><p>💡 <strong>提示</strong>：如果在某个知识点上卡住了，不要着急。试着回头复习一下前面的章节，或者在<a href="https://baike.baidu.com/" target="_blank" rel="noreferrer">电路课本</a>中查找相关概念。</p></blockquote><h2 id="开始学习" tabindex="-1">开始学习 <a class="header-anchor" href="#开始学习" aria-label="Permalink to &quot;开始学习&quot;">​</a></h2><p>准备好了吗？从 <strong><a href="/pyspice/tutorial/setup.html">环境配置安装</a></strong> 开始，搭建你的 Python 电路仿真环境！</p><p>如果你已经配好了环境，可以直接跳到感兴趣的章节：</p><ul><li><a href="/pyspice/tutorial/middle-school/ch01-circuit-current.html">初中篇：第1章 电路与电流</a></li><li><a href="/pyspice/tutorial/high-school/ch01-electric-field.html">高中篇：第1章 电场与电势</a></li><li><a href="/pyspice/tutorial/college/ch01-kirchhoff.html">高校篇：第1章 基尔霍夫定律与节点分析</a></li></ul>',17)])])}const g=a(l,[["render",i]]);export{u as __pageData,g as default};
